import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-BTt50lwF.js";var i=JSON.parse(`{"path":"/vm/pve/84ifbnwh/","title":"禁止 Crontab 执行时发送邮件 | Proxmox VE","lang":"zh-CN","frontmatter":{"title":"禁止 Crontab 执行时发送邮件","createTime":"2026/08/29 22:50:00","permalink":"/vm/pve/84ifbnwh/"},"readingTime":{"minutes":1.23,"words":369},"git":{},"filePathRelative":"vm/pve/002.crontab-suppress-mail.md","headers":[]}`),a={name:`002.crontab-suppress-mail.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>cron 在执行任务时，若命令产生标准输出或标准错误，默认会通过本地邮件系统把输出发送给任务所属用户（邮件通常存放在 <code>/var/spool/mail</code>）。当任务频繁执行或脚本持续输出时，会不断产生邮件。本文记录两种禁用方式：全局关闭 cron 邮件（设置 <code>MAILTO</code> 为空），以及单条任务把输出重定向到黑洞。</p><p>参考来源：</p><ul><li><a href="https://www.cnblogs.com/varden/p/15178582.html" target="_blank" rel="noopener noreferrer">禁止 cron 发送邮件及任务输出重定向</a></li><li><a href="https://blog.csdn.net/E_Possible/article/details/108065129" target="_blank" rel="noopener noreferrer">设置 Crontab 执行任务时不发送邮件</a></li></ul><h2 id="一、禁止-cron-发送邮件" tabindex="-1"><a class="header-anchor" href="#一、禁止-cron-发送邮件"><span>一、禁止 cron 发送邮件</span></a></h2><p>编辑系统级 crontab 配置文件 <code>/etc/crontab</code>，将 <code>MAILTO</code> 参数设为空：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SHELL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/sbin:/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设置 MAILTO 参数为空，cron 不再发送邮件</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MAILTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HOME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/</span></span></code></pre></div><p>设为空后，cron 不会将任务输出通过邮件发送。</p><h2 id="二、任务输出重定向" tabindex="-1"><a class="header-anchor" href="#二、任务输出重定向"><span>二、任务输出重定向</span></a></h2><p>执行 <code>crontab -e</code> 编辑用户级任务，在命令末尾重定向输出。两种写法二选一：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 写法一：分别重定向标准输出与标准错误到 /dev/null</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /shell/shell.sh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/dev/null </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;&amp;1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 写法二：将标准输出与标准错误一并重定向（bash 语法）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /shell/shell.sh &amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /dev/null</span></span></code></pre></div><div class="hint-container note"><p class="hint-container-title">笔记</p><p><code>&gt;/dev/null 2&gt;&amp;1</code> 把标准输出（<code>1</code>）和标准错误（<code>2</code>）都导向 <code>/dev/null</code>；</p><p><code>&amp;&gt; /dev/null</code> 是等价的 bash 简写。</p><p>两者都能彻底抑制任务产生的邮件与日志输出。</p></div>`,12)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};